%000000                     end else store_lane<=store_lane+1;
-000000  point: type=branch comment=else hier=arithmetic_tb.core
                        end
%000000                 FINISH: begin
-000000  point: type=line comment=case hier=arithmetic_tb.core
%000000                     out_valid<=1; out_frame_id<=active_id; out_logits<={logits[2],logits[1],logits[0]}; out_error<=arithmetic_errors;
-000000  point: type=line comment=case hier=arithmetic_tb.core
%000000                     if (logits[0]>=logits[1] && logits[0]>=logits[2]) out_class<=0;
-000000  point: type=line comment=elsif hier=arithmetic_tb.core
-000000  point: type=expr comment=(((logits[2'h0]) >= (logits[2'h1]))==0) => 0 hier=arithmetic_tb.core
-000000  point: type=expr comment=(((logits[2'h0]) >= (logits[2'h1]))==1 && ((logits[2'h0]) >= (logits[2'h2]))==1) => 1 hier=arithmetic_tb.core
-000000  point: type=expr comment=(((logits[2'h0]) >= (logits[2'h2]))==0) => 0 hier=arithmetic_tb.core
%000000                     else if (logits[1]>=logits[2]) out_class<=1; else out_class<=2;
-000000  point: type=line comment=if hier=arithmetic_tb.core
-000000  point: type=line comment=else hier=arithmetic_tb.core
%000000                     cycles_pre<=32'(count_pre); cycles_dft<=32'(count_dft); cycles_power<=32'(count_power); cycles_nn<=32'(count_nn); cycles_total<=32'(count_total);
-000000  point: type=line comment=case hier=arithmetic_tb.core
%000000                     state<=HOLD;
-000000  point: type=line comment=case hier=arithmetic_tb.core
                        end
%000000                 HOLD: if (out_valid && out_ready) begin out_valid<=0; state<=IDLE; end
-000000  point: type=line comment=case hier=arithmetic_tb.core
-000000  point: type=branch comment=if hier=arithmetic_tb.core
-000000  point: type=branch comment=else hier=arithmetic_tb.core
-000000  point: type=expr comment=(out_ready==0) => 0 hier=arithmetic_tb.core
-000000  point: type=expr comment=(out_valid==0) => 0 hier=arithmetic_tb.core
-000000  point: type=expr comment=(out_valid==1 && out_ready==1) => 1 hier=arithmetic_tb.core
%000000                 default: state<=IDLE;
-000000  point: type=line comment=case hier=arithmetic_tb.core
                    endcase
                end
            end
        `ifdef VIB_ASSERT
            initial begin
                assert (N >= 8 && (N & (N-1)) == 0);
                assert (LANES == 1 || LANES == 4);
                assert (BANDS == 1 || BANDS == 3);
            end
            always @(posedge clk) if (!rst) begin
                assert ((full & busy) == 0);
                if (in_valid && in_ready && (restart_input || !draining))
                    assert (!full[write_bank] && !busy[write_bank]);
                if (state == PRE_READ) assert (busy[active_bank]);
                if (state == DFT_STORE) assert (int'(dft_group)+int'(store_lane) < COMPONENTS && int'(store_lane) < LANES);
                if (state == NN_READ) assert (int'(weight_address) < WEIGHT_WORDS);
                if (state == POWER_IM_ADD) assert (!band_sum_next[33]);
            end
            assert property (@(posedge clk) disable iff (rst)
                out_valid && !out_ready |=> out_valid && $stable({out_frame_id,
                out_logits,out_class,out_error,cycles_pre,cycles_dft,cycles_power,
                cycles_nn,cycles_total}));
        `endif
        endmodule
        
